CREATE TABLE [purchase].[SupplierAddresses] ([AddressId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SupplierAddresses_Id] DEFAULT NEWSEQUENTIALID(), [SupplierId] UNIQUEIDENTIFIER NOT NULL, [AddressType] NVARCHAR(30) NOT NULL, [AddressLine1] NVARCHAR(250) NOT NULL, [AddressLine2] NVARCHAR(250) NULL, [City] NVARCHAR(100) NOT NULL, [District] NVARCHAR(100) NULL, [State] NVARCHAR(100) NOT NULL, [Country] NVARCHAR(100) NOT NULL CONSTRAINT [DF_SupplierAddresses_Country] DEFAULT 'India', [PostalCode] NVARCHAR(10) NOT NULL, CONSTRAINT [PK_SupplierAddresses] PRIMARY KEY ([AddressId]), CONSTRAINT [FK_SupplierAddresses_Suppliers] FOREIGN KEY ([SupplierId]) REFERENCES [purchase].[Suppliers]([SupplierId]) ON DELETE CASCADE);
GO
CREATE INDEX [IX_SupplierAddresses_SupplierId] ON [purchase].[SupplierAddresses]([SupplierId]);
